/** Base bank above + keyed CAA-paper boost (numeric-calc & scenario items). */
export const MET_QUESTIONS: MetQuestion[] = [
  ...MET_BASE_QUESTIONS,
  ...MET_BOOST_QUESTIONS,
  ...MET_GAP_QUESTIONS,
];

/** All questions belonging to one SACAA section, e.g. "A.8.12". */
export function getQuestionsBySection(sectionId: string): MetQuestion[] {
  return MET_QUESTIONS.filter((q) => q.sectionId === sectionId);
}

export const MET_QUESTION_COUNT = MET_QUESTIONS.length;
